def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._keys.keys())

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if isinstance(protocol_version, tuple):
        if protocol_version in cls.SUPPORTED_PROTOCOLS:
            return {protocol_version: cls.PROTOCOL_HANDLERS[protocol_version]}
        else:
            return {}
    elif protocol_version is None:
        return {p: cls.PROTOCOL_HANDLERS[p] for p in cls.SUPPORTED_PROTOCOLS}
    else:
        raise TypeError("protocol version must be a tuple")

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index[key]
    except KeyError:
        return -1

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if keys:
        values = []
        for key in keys:
            if key in self._data:
                values.append(self._data[key])
        return values
    else:
        return list(self._data.values())

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        keys = list(self._data.keys())
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError("index out of range")
            result[self._fields[key]] = self._data[key]
        else:
            if key not in self._data:
                result[key] = None
            else:
                result[key] = self._data[key]
    return result

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer.
    If the number is halfway between two integers,
    it is rounded to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n - int(n) == 0.5:
        if int(n) % 2 == 0:
            return int(n)
        else:
            return int(n) + 1
    return int(n)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    if not fields or len(fields) < 1:
        raise ValueError('At least one field name must be provided')

    field_names = []
    for field in fields:
        if not isinstance(field, str):
            raise ValueError(f'Field names must be strings: {field!r}')
        if not field.isidentifier():
            raise ValueError(f'Field names must be valid identifiers: {field!r}')
        if keyword.iskeyword(field):
            raise ValueError(f'Field names must not be keywords: {field!r}')
        if field in field_names:
            raise ValueError(f'Field names must be unique: {field!r}')
        field_names.append(field)

    dtype = {'names': field_names, 'formats': ['<f8'] * len(field_names)}

    class Point(np.ndarray):
        __doc__ = f'{name} subclass with fields {field_names}'

        def __new__(cls, input_array, copy=False):
            if copy:
                input_array = np.array(input_array, copy=True)
            obj = np.ndarray.__new__(cls, shape=input_array.shape, dtype=dtype, buffer=input_array)
            return obj

        def __array_finalize__(self, obj):
            if self.base is None:
                return
            if isinstance(obj, Point):
                # This was likely a slicing operation, and we need to set our
                # Point attributes from the obj.
                for field in field_names:
                    setattr(self, field, getattr(obj, field))

        def __getattr__(self, name):
            if name in field_names:
                return self[name]
            raise AttributeError

        def __setattr__(self, name, value):
            if name in field_names:
                self[name] = value
            else:
                object.__setattr__(self, name, value)

        def __reduce__(self):
            return (_point_type, (self.dtype, self.shape, self.strides, self.names, self.srid_map))

    return Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def deprecated_decorator(func):
        @functools.wraps(func)
        def deprecated_func(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return deprecated_func
    return deprecated_decorator

