def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    m = re.match(r"([0-9]+)\.([0-9]+)\.([0-9]+)", s)
    if m is None:
        return (-1, -1, -1)
    else:
        major, minor, patch = m.groups()
        return (int(major), int(minor), int(patch))

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize: int = 128, ttl: int = 600, timer: Callable = time.monotonic, typed: bool = False) -> Callable:
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    sentinel = object()
    make_key = _make_key_factory(typed)
    cache = {}
    stats = [CacheInfo(0, 0, maxsize, ttl)]
    _timer = timer

    def wrapper(func):
        @wraps(func)
        def memoized_func(*args, **kwargs):
            key = make_key(*args, **kwargs)
            nonlocal stats
            try:
                value, expiration_time = cache[key]
                if expiration_time > _timer():
                    stats[0].hits += 1
                    return value
            except KeyError:
                pass

            value = func(*args, **kwargs)
            cache[key] = (value, _timer() + ttl)
            stats[0].misses += 1

            if len(cache) > maxsize:
                for key, (_, expiration_time) in list(cache.items()):
                    if expiration_time < _timer():
                        cache.pop(key)

            return value

        def cache_info():
            return stats[0]

        def cache_clear():
            nonlocal cache, stats
            cache = {}
            stats = [CacheInfo(0, 0, maxsize, ttl)]

        memoized_func.cache_info = cache_info
        memoized_func.cache_clear = cache_clear
        return memoized_func

    return wrapper

