def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if not interfaces.providedBy(object):
        return None

    directlyProvided = interfaces.directlyProvidedBy(object)
    for name, value in directlyProvided:
        if name == "provides":
            return value

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
    return sorted(seen, key=lambda x: x.__name__)

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    return {key: value.__doc__ for key, value in self.__dict__.items() if not key.startswith("_") or all}

def _normalizeargs(sequence, output=None):
    if output is None:
        output = []
    if isinstance(sequence, (InterfaceClass, Broken)):
        output.append(sequence)
    elif isinstance(sequence, tuple):
        for v in sequence:
            _normalizeargs(v, output)
    else:
        for v in sequence.__bases__:
            _normalizeargs(v, output)
    return output

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    error_indexes = []
    for idx, (cname, var) in enumerate(self._variables.items()):
        if cname.startswith(coord_name + "_") and var.role == "error":
            error_indexes.append(idx)
    return error_indexes

def is_fill_request_seq(seq: typing.Sequence) -> bool:
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, collections.abc.Sequence) and any(isinstance(item, FillRequest) for item in seq):
        return True
    if isinstance(seq, Source):
        return False
    return True

