def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    diff = {}
    for k in d1:
        if k not in d2:
            diff[k] = d1[k]
        elif not isinstance(d1[k], dict) or not isinstance(d2[k], dict):
            if d1[k] != d2[k]:
                diff[k] = d1[k]
        else:
            diff[k] = difference(d1[k], d2[k], level - 1)
    return diff

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    """
    new_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            new_dict[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            new_dict[key] = generate_default_observer_schema_list(value)
        else:
            new_dict[key] = None

    if first_level:
        for key in ["apiVersion", "kind", "metadata"]:
            new_dict[key] = manifest_dict[key]

    return new_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(last_applied_manifest)):
        if isinstance(last_applied_manifest[i], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], observer_schema[i], response[i])
        elif isinstance(last_applied_manifest[i], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observer_schema[i], response[i])
        else:
            last_applied_manifest[i] = response[i]

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, val in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")

        if isinstance(val, dict):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], val, response[field])
        else:
            last_applied_manifest[field] = response[field]

    for field, val in response.items():
        if field not in observer_schema:
            last_applied_manifest[field] = val

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if not resource.observer:
            resource.observer = Observer.generate_default(resource.kind)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is a valid OCFL object
    if not os.path.isdir(path) or not os.path.exists(os.path.join(path, " inventory.json")):
        return False

    # Check if inventory.json is valid
    try:
        with open(os.path.join(path, "inventory.json"), "r") as f:
            inventory = json.load(f)
            if not inventory["id"] or not inventory["root"] or not inventory["manifest"]:
                return False
    except json.JSONDecodeError:
        return False

    return True

