def validate(self, inventory, extract_spec_version=False):
    if extract_spec_version:
        type_value = inventory.get("type")
        if type_value and isinstance(type_value, str):
            spec_version = type_value.split("-")[0]
            if spec_version not in self.valid_spec_versions:
                raise ValueError("Invalid specification version: %s" % spec_version)
            else:
                self.spec_version = spec_version

    if self.spec_version not in self.valid_spec_versions:
        raise ValueError("Invalid specification version: %s" % self.spec_version)

    for section in self.sections:
        section_name = section[0]
        section_values = inventory.get(section_name)
        if section_values and not isinstance(section_values, list):
            raise ValueError("Section '%s' must be a list" % section_name)
        for item in section_values:
            if not isinstance(item, self.get_item_type(section_name)):
                raise ValueError("Invalid item in section '%s': %s" % (section_name, item))

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                digest = line.split(' ', 1)[0]
                if digest not in digests_used:
                    print('Digest {} is not used in the config.'.format(digest))
                if digest not in self._digests_present:
                    print('Digest {} is not present in the manifest.'.format(digest))
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check if both inventories have the same number of parameters
    if len(self.parameters) != len(prior.parameters):
        raise ValueError("Prior and current inventory objects have different number of parameters")

    # Check if both inventories have the same parameters
    if set(self.parameters) != set(prior.parameters):
        raise ValueError("Prior and current inventory objects have different parameters")

    # Check if both inventories have the same number of species
    if len(self.species) != len(prior.species):
        raise ValueError("Prior and current inventory objects have different number of species")

    # Check if both inventories have the same species
    if set(self.species) != set(prior.species):
        raise ValueError("Prior and current inventory objects have different species")

    # Check if both inventories have the same stoichiometry matrix
    if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
        raise ValueError("Prior and current inventory objects have different stoichiometry matrix shapes")

    if not np.array_equal(self.stoichiometry_matrix.data, prior.stoichiometry_matrix.data):
        raise ValueError("Prior and current inventory objects have different stoichiometry matrix data")

    # Check if both inventories have the same propensities
    if self.propensities.shape != prior.propensities.shape:
        raise ValueError("Prior and current inventory objects have different propensities shapes")

    if not np.array_equal(self.propensities.data, prior.propensities.data):
        raise ValueError("Prior and current inventory objects have different propensities data")

    # Check if both inventories have the same initial state
    if len(self.initial_state) != len(prior.initial_state):
        raise ValueError("Prior and current inventory objects have different initial state lengths")

    if not np.array_equal(self.initial_state, prior.initial_state):
        raise ValueError("Prior and current inventory objects have different initial state")

    # Check if both inventories have the same number of events
    if len(self.events) != len(prior.events):
        raise ValueError("Prior and current inventory objects have different number of events")

    # Check if both inventories have the same events
    for event in self.events:
        if event not in prior.events:
            raise ValueError("Prior and current inventory objects have different events")

    # Check if both inventories have the same parameters in events
    for event in self.events:
        if set(self.events[event].parameters) != set(prior.events[event].parameters):
            raise ValueError("Prior and current inventory objects have different parameters in events")

    # Check if both inventories have the same number of observers
    if len(self.observers) != len(prior.observers):
        raise ValueError("Prior and current inventory objects have different number of observers")

    # Check if both inventories have the same observers
    for observer in self.observers:
        if observer not in prior.observers:
            raise ValueError("Prior and current inventory objects have different observers")

    # Check if both inventories have the same parameters in observers
    for observer in self.observers:
        if set(self.observers[observer].parameters) != set(prior.observers[observer].parameters):
            raise ValueError("Prior and current inventory objects have different parameters in observers")

    # Check if both inventories have the same number of models
    if len(self.models) != len(prior.models):
        raise ValueError("Prior and current inventory objects have different number of models")

    # Check if both inventories have the same models
    for model in self.models:
        if model not in prior.models:
            raise ValueError("Prior and current inventory objects have different models")

    # Check if both inventories have the same parameters in models
    for model in self.models:
        if set(self.models[model].parameters) != set(prior.models[model].parameters):
            raise ValueError("Prior and current inventory objects have different parameters in models")

    # Check if both inventories have the same number of simulations
    if len(self.simulations) != len(prior.simulations):
        raise ValueError("Prior and current inventory objects have different number of simulations")

    # Check if both inventories have the same simulations
    for simulation in self.simulations:
        if simulation not in prior.simulations:
            raise ValueError("Prior and current inventory objects have different simulations")

    # Check if both inventories have the same results
    for simulation in self.simulations:
        if self.simulations[simulation] != prior.simulations[simulation]:
            raise ValueError("Prior and current inventory objects have different simulations")

    # Check if both inventories have the same plotting
    if self.plotting != prior.plotting:
        raise ValueError("Prior and current inventory objects have different plotting attributes")

def validate_fixity(self, fixity, manifest_files):
