        raise TypeError("Fixity block must be a dictionary")

    for algorithm, values in fixity.items():
        if not isinstance(values, dict):
            raise TypeError("Values in fixity block must be dictionaries")

        for file_path, checksum in values.items():
            if file_path not in manifest_files:
                raise ValueError("File {} not found in manifest".format(file_path))

            if not isinstance(checksum, str):
                raise TypeError("Checksum for {} must be a string".format(file_path))

            try:
                int(checksum, 16)
            except ValueError:
                raise ValueError("Checksum for {} must be a hexadecimal string".format(file_path))

            if len(checksum) != len(manifest_files[file_path]["size"]):
                raise ValueError(
