def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list of strings")
    if not all(isinstance(c, str) for c in alphabet):
        raise ValueError("alphabet must be a list of strings")
    if not len(alphabet) >= 2:
        raise ValueError("alphabet must have at least 2 strings")
    if not all(len(c) == 1 for c in alphabet):
        raise ValueError("alphabet must be a list of single characters")
    if not all(c.isalnum() for c in alphabet):
        raise ValueError("alphabet must be a list of alphanumeric characters")
    if number == 0:
        return alphabet[0]
    base = len(alphabet)
    result = ""
    while number > 0:
        number, digit = divmod(number, base)
        result = alphabet[digit] + result
    if padding is not None:
        result = result.rjust(padding, alphabet[0])
    return result

