def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if self._head is None:
        raise KeyError("list is empty")
    node = self._head[2]
    while node is not self._tail:
        if node[1] < self._head[1]:
            self._head = node[2]
            return (node[0], node[1])
        node = node[2]

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self.data:
        raise KeyError("list is empty")
    key, value = self.data.popitem()
    return key, value

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    item = self._head[2]
    while item is self._tail:
        item = self._find_lt(item[0])
    self._remove(item)
    return (item[0], item[1])

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if not request.headers.get("Authorization", None):
        return False
    authorization = request.headers["Authorization"]
    if not authorization.startswith("Bearer "):
        return False
    token = authorization[len("Bearer "):]
    if not token:
        return False
    try:
        decoded = jwt.decode(token, algorithms=["ES256"], verify=False)
        if not decoded:
            return False
        if not decoded["matrix"].startswith("mxc://"):
            return False
        return True
    except jwt.InvalidTokenError:
        return False
    return False

