def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = self._default_spec.to_default_dict()
    args_defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to resolve default for non-Option type')

        if not isinstance(arg.default, NoDefault):
            args_defaults[arg.name] = arg.default

        if isinstance(arg, DictOption):
            if arg.scheme:
                spec_defaults[arg.name] = arg.scheme.build_defaults()
    return {**spec_defaults, **args_defaults}

def get_deprecated_args(self):
    """Return a dict with options which deprecate others."""

    return {
        'metadata': 'meta',
        'private_key': 'key_path',
        'cipher': 'encryption',
        'cipher_mode': 'encryption_mode'
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if there are deprecated arguments in the answer file
    for arg_name, arg_value in answer_file_args.items():
        if arg_name in self.deprecated_args:
            print("Warning: deprecated argument '{}' found in answer file. It will be ignored.".format(arg_name))
    # Check if there are deprecated arguments in the cli args
    for arg_name, arg_value in cli_args.items():
        if arg_name in self.deprecated_args:
            print("Warning: deprecated argument '{}' found in CLI args. It will be ignored.".format(arg_name))

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided.

    :param args: The arguments provided by the user.
    :type args: List[str]
    """

    if args is None or len(args) == 0:
        raise ValueError("Missing required arguments.")

    for argument in self.required_arguments:
        if argument not in args:
            raise ValueError("Missing required argument: {}".format(argument))

def _get_conditionally_required_args(command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if option.get('required_when'):
            required_when = option['required_when']
            if command_name in required_when and required_when[command_name] in args:
                required_args.append(option['name'])
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.len_:
            return False
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args.items():
        if arg not in self.choices:
            msg = "Invalid choice: {0}"
            raise ValueError(msg.format(arg))

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < self.min_value or arg > self.max_value:
            raise ValueError("Invalid argument value: %s. Must be between %s and %s." % (arg, self.min_value, self.max_value))

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg] = args[arg]
        elif arg.startswith('--nested-'):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        # Convert args.ssh_key_file to str
        if "ssh_key_file" in values_dict:
            values_dict["ssh_key_file"] = str(values_dict["ssh_key_file"])
        # Convert args.remote_dir to str
        if "remote_dir" in values_dict:
            values_dict["remote_dir"] = str(values_dict["remote_dir"])
        # Convert args.host to str
        if "host" in values_dict:
            values_dict["host"] = str(values_dict["host"])
        # Convert args.port to int
        if "port" in values_dict:
            values_dict["port"] = int(values_dict["port"])
        # Convert args.user to str
        if "user" in values_dict:
            values_dict["user"] = str(values_dict["user"])
        # Convert args.password to str
        if "password" in values_dict:
            values_dict["password"] = str(values_dict["password"])
        # Convert args.verbose to bool
        if "verbose" in values_dict:
            values_dict["verbose"] = bool(values_dict["verbose"])
        # Convert args.quiet to bool
        if "quiet" in values_dict:
            values_dict["quiet"] = bool(values_dict["quiet"])
    elif parser_name == "virsh":
        # Convert args.xml to str
        if "xml" in values_dict:
            values_dict["xml"] = str(values_dict["xml"])
        # Convert args.uri to str
        if "uri" in values_dict:
            values_dict["uri"] = str(values_dict["uri"])
        # Convert args.password to str
        if "password" in values_dict:
            values_dict["password"] = str(values_dict["password"])
    elif parser_name == "ospd":
        # Convert args.ssh_key_file to str
        if "ssh_key_file" in values_dict:
            values_dict["ssh_key_file"] = str(values_dict["ssh_key_file"])
        # Convert args.hosts to str
        if "hosts" in values_dict:
            values_dict["hosts"] = str(values_dict["hosts"])
        # Convert args.verbose to bool
        if "verbose" in values_dict:
            values_dict["verbose"] = int(values_dict["verbose"])
        # Convert args.quiet to bool
        if "quiet" in values_dict:
            values_dict["quiet"] = int(values_dict["quiet"])

    return values_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if "ENV_CONFIG_PATH" not in os.environ:
        config_path = self.get_config_path()
        logger.debug("Setting ENV_CONFIG_PATH to {}".format(config_path))
        os.environ["ENV_CONFIG_PATH"] = config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise Exception("Path '{0}' does not start with root '{1}'".format(path, root))
    return path[len(root):]
